import type { Comment, Post } from './posts'

const API_URL = 'https://jsonplaceholder.typicode.com'

async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init)

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`)
  }

  return (await response.json()) as T
}

export function getRecentPosts(): Promise<Post[]> {
  return fetchJson<Post[]>(`${API_URL}/posts?_limit=5`, {
    cache: 'no-store',
  })
}

export function getPosts(): Promise<Post[]> {
  return fetchJson<Post[]>(`${API_URL}/posts`, {
    next: { revalidate: 60 },
  })
}

export function getPost(id: string): Promise<Post> {
  return fetchJson<Post>(`${API_URL}/posts/${encodeURIComponent(id)}`, {
    next: { revalidate: 300 },
  })
}

export function getComments(id: string): Promise<Comment[]> {
  return fetchJson<Comment[]>(
    `${API_URL}/posts/${encodeURIComponent(id)}/comments`,
    { next: { revalidate: 300 } },
  )
}

