import type { Metadata } from 'next'
import { notFound } from 'next/navigation'

import { BackButton } from '@/components/back-button'
import { getComments, getPost, getPosts } from '@/lib/json-placeholder'
import type { Post } from '@/lib/posts'

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

async function loadPost(id: string): Promise<Post | null> {
  try {
    const post = await getPost(id)
    return post.id ? post : null
  } catch {
    return null
  }
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await loadPost(id)

  if (!post) {
    return { title: 'Post Not Found' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: BlogPostPageProps) {
  const { id } = await params
  let post: Post | null
  let comments: Awaited<ReturnType<typeof getComments>>

  try {
    ;[post, comments] = await Promise.all([loadPost(id), getComments(id)])
  } catch {
    notFound()
  }

  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <section key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </section>
        ))}
      </div>
    </article>
  )
}
