import { apiPosts, type PostInput } from '@/lib/posts'

function isPostInput(value: unknown): value is PostInput {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  const input = value as Record<string, unknown>
  return typeof input.title === 'string' && typeof input.content === 'string'
}

export function GET() {
  return Response.json(apiPosts)
}

export async function POST(request: Request) {
  let body: unknown

  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  if (!isPostInput(body) || !body.title.trim() || !body.content.trim()) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 },
    )
  }

  return Response.json(
    {
      id: Date.now(),
      title: body.title,
      content: body.content,
      createdAt: new Date().toISOString(),
    },
    { status: 201 },
  )
}
