import type { PostUpdate } from '@/lib/posts'

interface PostRouteContext {
  params: Promise<{ id: string }>
}

function parseId(id: string): number | null {
  const parsedId = Number.parseInt(id, 10)
  return Number.isNaN(parsedId) ? null : parsedId
}

function isPostUpdate(value: unknown): value is PostUpdate {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return false
  }

  const input = value as Record<string, unknown>
  return (
    (input.title === undefined || typeof input.title === 'string') &&
    (input.content === undefined || typeof input.content === 'string')
  )
}

export async function GET(_request: Request, { params }: PostRouteContext) {
  const { id } = await params
  const parsedId = parseId(id)

  if (parsedId === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  return Response.json({
    id: parsedId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  })
}

export async function PUT(request: Request, { params }: PostRouteContext) {
  const { id } = await params
  const parsedId = parseId(id)

  if (parsedId === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  let body: unknown

  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  if (!isPostUpdate(body)) {
    return Response.json({ error: 'Invalid post data' }, { status: 400 })
  }

  return Response.json({
    id: parsedId,
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  })
}

export async function DELETE(_request: Request, { params }: PostRouteContext) {
  const { id } = await params

  if (parseId(id) === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  return Response.json({ message: `Post ${id} deleted successfully` })
}
